-- M01: 전체 테이블 존재
WITH checked AS (
SELECT e.t AS item, IF(a.TABLE_NAME IS NOT NULL,1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.tables[*]' COLUMNS (t VARCHAR(64) PATH '$.table')) e
LEFT JOIN information_schema.TABLES a ON a.TABLE_SCHEMA=DATABASE() AND a.TABLE_NAME=e.t AND a.TABLE_TYPE='BASE TABLE'
)
SELECT 'M01 전체 테이블 존재' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- M02: 컬럼 타입 NULL 자동번호 생성컬럼
WITH checked AS (
SELECT CONCAT(e.t,'.',e.c) AS item,
 IF(a.COLUMN_NAME IS NOT NULL
 AND REGEXP_REPLACE(LOWER(a.COLUMN_TYPE),'^(tinyint|smallint|mediumint|int|bigint)\\([0-9]+\\)','$1')=REGEXP_REPLACE(e.ty,'^(tinyint|smallint|mediumint|int|bigint)\\([0-9]+\\)','$1')
 AND a.IS_NULLABLE=e.nu
 AND (LOCATE('auto_increment',a.EXTRA)>0)=e.au
 AND (CHAR_LENGTH(a.GENERATION_EXPRESSION)>0)=e.ge
 AND (e.cs='' OR a.CHARACTER_SET_NAME=e.cs) AND (e.co='' OR a.COLLATION_NAME=e.co),1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.columns[*]' COLUMNS (t VARCHAR(64) PATH '$.table', c VARCHAR(64) PATH '$.column', ty VARCHAR(1024) PATH '$.type', nu VARCHAR(3) PATH '$.nullable', au INT PATH '$.auto', ge INT PATH '$.generated', cs VARCHAR(64) PATH '$.charset', co VARCHAR(64) PATH '$.collation')) e
LEFT JOIN information_schema.COLUMNS a ON a.TABLE_SCHEMA=DATABASE() AND a.TABLE_NAME=e.t AND a.COLUMN_NAME=e.c
)
SELECT 'M02 컬럼 타입 NULL 자동번호 생성컬럼' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- M03: 기본키 UNIQUE 컬럼 순서
WITH checked AS (
SELECT CONCAT(e.t,'.',e.n) AS item, IF(a.cols=e.cols,1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.keys[*]' COLUMNS (t VARCHAR(64) PATH '$.table', n VARCHAR(64) PATH '$.name', cols VARCHAR(1024) PATH '$.columns')) e
LEFT JOIN (SELECT TABLE_NAME,INDEX_NAME,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX SEPARATOR ',') AS cols
 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND NON_UNIQUE=0 GROUP BY TABLE_NAME,INDEX_NAME) a
ON a.TABLE_NAME=e.t AND a.INDEX_NAME=e.n
)
SELECT 'M03 기본키 UNIQUE 컬럼 순서' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- M04: 외래키 대상 삭제 규칙
WITH checked AS (
SELECT CONCAT(e.t,'.',e.n) AS item,
 IF(k.COLUMN_NAME=e.c AND k.REFERENCED_TABLE_SCHEMA=DATABASE() AND k.REFERENCED_TABLE_NAME=e.rt AND k.REFERENCED_COLUMN_NAME=e.rc AND r.DELETE_RULE=e.dr,1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.fks[*]' COLUMNS (t VARCHAR(64) PATH '$.table', n VARCHAR(64) PATH '$.name', c VARCHAR(64) PATH '$.column', rt VARCHAR(64) PATH '$.target', rc VARCHAR(64) PATH '$.target_column', dr VARCHAR(20) PATH '$.delete_rule')) e
LEFT JOIN information_schema.KEY_COLUMN_USAGE k ON k.CONSTRAINT_SCHEMA=DATABASE() AND k.TABLE_NAME=e.t AND k.CONSTRAINT_NAME=e.n
LEFT JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=DATABASE() AND r.TABLE_NAME=e.t AND r.CONSTRAINT_NAME=e.n
)
SELECT 'M04 외래키 대상 삭제 규칙' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- M05: CHECK 존재 및 활성화
WITH checked AS (
SELECT CONCAT(e.t,'.',e.n) AS item, IF(a.ENFORCED='YES',1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.checks[*]' COLUMNS (t VARCHAR(64) PATH '$.table', n VARCHAR(64) PATH '$.name')) e
LEFT JOIN information_schema.TABLE_CONSTRAINTS a ON a.CONSTRAINT_SCHEMA=DATABASE() AND a.TABLE_NAME=e.t AND a.CONSTRAINT_NAME=e.n AND a.CONSTRAINT_TYPE='CHECK'
)
SELECT 'M05 CHECK 존재 및 활성화' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- M06: VIEW 존재 및 출력 컬럼
WITH checked AS (
SELECT e.n AS item,IF(v.TABLE_NAME IS NOT NULL AND a.cols=e.cols,1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.views[*]' COLUMNS (n VARCHAR(64) PATH '$.name', cols VARCHAR(1024) PATH '$.columns')) e
LEFT JOIN information_schema.VIEWS v ON v.TABLE_SCHEMA=DATABASE() AND v.TABLE_NAME=e.n
LEFT JOIN (SELECT TABLE_NAME,GROUP_CONCAT(COLUMN_NAME ORDER BY ORDINAL_POSITION SEPARATOR ',') AS cols
 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() GROUP BY TABLE_NAME) a ON a.TABLE_NAME=e.n
)
SELECT 'M06 VIEW 존재 및 출력 컬럼' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- M07: InnoDB 저장 엔진
WITH checked AS (
SELECT e.t AS item,IF(a.ENGINE='InnoDB',1,0) AS ok
FROM JSON_TABLE(@zip_audit_expected, '$.tables[*]' COLUMNS (t VARCHAR(64) PATH '$.table')) e
LEFT JOIN information_schema.TABLES a ON a.TABLE_SCHEMA=DATABASE() AND a.TABLE_NAME=e.t
)
SELECT 'M07 InnoDB 저장 엔진' AS test, IF(COALESCE(SUM(ok=0),0)=0,'PASS','FAIL') AS result,
 COUNT(*) AS checked_count, COALESCE(SUM(ok=0),0) AS failed_count,
 GROUP_CONCAT(CASE WHEN ok=0 THEN item END ORDER BY item SEPARATOR ', ') AS failed_items
FROM checked;

-- 추가 객체는 사용자/보관용일 수 있으므로 삭제하지 않고 검토 목록으로 표시합니다.
SELECT a.TABLE_NAME AS extra_object,a.TABLE_TYPE
FROM information_schema.TABLES a
WHERE a.TABLE_SCHEMA=DATABASE() AND a.TABLE_NAME NOT IN (
 SELECT t FROM JSON_TABLE(@zip_audit_expected, '$.tables[*]' COLUMNS (t VARCHAR(64) PATH '$.table')) x
 UNION ALL SELECT n FROM JSON_TABLE(@zip_audit_expected, '$.views[*]' COLUMNS (n VARCHAR(64) PATH '$.name')) y);

-- 기대값에 없는 추가 컬럼도 확인합니다.
SELECT a.TABLE_NAME,a.COLUMN_NAME AS extra_column
FROM information_schema.COLUMNS a
WHERE a.TABLE_SCHEMA=DATABASE()
 AND a.TABLE_NAME IN (SELECT t FROM JSON_TABLE(@zip_audit_expected, '$.tables[*]' COLUMNS (t VARCHAR(64) PATH '$.table')) x)
 AND NOT EXISTS (SELECT 1 FROM JSON_TABLE(@zip_audit_expected, '$.columns[*]' COLUMNS (t VARCHAR(64) PATH '$.table', c VARCHAR(64) PATH '$.column')) e WHERE e.t=a.TABLE_NAME AND e.c=a.COLUMN_NAME);
SET SESSION group_concat_max_len=@zip_audit_old_group_concat;
